"""AI Remediation Agent.

Generates safe, drop-in replacement patterns and architectural explanations
for detected security and quality findings.
"""

from typing import Dict, List, Any


class RemediationAgent:
    """Enhances findings with contextual remediated code and safety rationale."""

    DISCLAIMER = (
        "NOTICE: All remediations generated by this agent are educational recommendations "
        "and architectural patterns. Every fix must be verified and tested by a human "
        "software engineer prior to production deployment."
    )

    def enhance_findings(self, findings: List[Dict[str, Any]], source_code: str) -> List[Dict[str, Any]]:
        """Attach side-by-side diff pairs, explanations, and review labels to findings."""
        enhanced = []
        source_lines = source_code.splitlines()

        for f in findings:
            item = dict(f)
            line_no = item.get("line_number", 1)

            # Extract 3-line original context
            start_idx = max(0, line_no - 2)
            end_idx = min(len(source_lines), line_no + 1)
            original_context = "\n".join(source_lines[start_idx:end_idx])

            item["original_context"] = original_context or item.get("code_snippet", "")
            item["remediation_disclaimer"] = self.DISCLAIMER

            # Ensure remediated code is present
            if not item.get("remediated_code"):
                item["remediated_code"] = self._generate_fallback_remediation(item)

            enhanced.append(item)

        return enhanced

    def _generate_fallback_remediation(self, finding: Dict[str, Any]) -> str:
        rule_id = finding.get("rule_id", "")
        if "SQL" in rule_id:
            return "# Remediated: Parameterized SQL\ncursor.execute('SELECT * FROM table WHERE id = ?', (record_id,))"
        elif "CMD" in rule_id:
            return "# Remediated: Safe Subprocess Execution\nsubprocess.run(['command', arg], shell=False, check=True)"
        elif "SECRET" in rule_id:
            return "# Remediated: Environment Variable Injection\nSECRET_KEY = os.environ.get('SECRET_KEY')"
        elif "EVAL" in rule_id:
            return "# Remediated: Safe Literal Evaluation\nimport ast\nresult = ast.literal_eval(payload)"
        elif "DESER" in rule_id:
            return "# Remediated: Structured JSON\nimport json\ndata = json.loads(payload)"
        else:
            return "# Suggested Fix: Apply defensive input validation and bounds checking"
